# EPISODE 010: The Ethiopian Bible — why it has 81 books, and what is in them.
# Each entry: (kind, text, visual)
# Quotes (public domain only): King James Version (Acts 8:27, Jude 14, Psalm 68:31);
# Kebra Nagast, tr. E. A. Wallis Budge, The Queen of Sheba and Her Only Son Menyelek (London, 1922).
# Modern translations (e.g. of Meqabyan, or the Ethiopic Enoch by Knibb / Nickelsburg) are copyrighted and are NOT quoted.

S = [
 # ---------------------------------------------------------------- COLD OPEN
 ("vo", "Why does the Ethiopian Bible have eighty one books? Because Ethiopia's church kept copying books that most other churches had let go. But there is a twist: even in Ethiopia, the lists do not agree on which eighty one.", "bm_166"),
 ("vo", "One of those books, the Book of Enoch, is quoted in the New Testament, and it survives complete in only one ancient language: Ethiopia's own, called Ge'ez.", "ms_geez_1"),
 ("vo", "And in a mountain monastery in the north, monks still guard two Gospel books that scientists have dated to roughly fifteen hundred years ago.", "bm_178"),
 ("title", "THE ETHIOPIAN BIBLE|Why It Has 81 Books", "bq_014"),

 # ---------------------------------------------------------------- I
 ("chapter", "I|A Kingdom on the Red Sea", "bent_213"),
 ("vo", "Most Protestant Bibles have sixty six books. A Catholic Bible has seventy three. The Bible of the Ethiopian Orthodox Tewahedo Church is the largest of them all.", "bent_213"),
 ("vo", "To see why, start with a kingdom. Around the first centuries of our era, Aksum, in the highlands of what is now Ethiopia and Eritrea, traded across the Red Sea with Rome, Arabia and India.", "bent_209"),
 ("vo", "Its kings raised giant stone monuments, some of them more than twenty meters tall. They minted their own coins in gold. A third century Persian prophet, Mani, counted Aksum among the four great kingdoms of the world.", "bent_211"),
 ("vo", "This was not a distant corner of the Christian story. It was one of its first homes.", "bent_213"),

 # ---------------------------------------------------------------- II
 ("chapter", "II|Two Boys from Tyre", "dore_038"),
 ("vo", "The church historian Rufinus, writing around the year four hundred, tells how it began. A ship from Tyre stopped on the Red Sea coast. Locals attacked it, and killed almost everyone on board.", "dore_038"),
 ("vo", "Two young Christians survived, Frumentius and his brother, Aedesius. They were taken to the royal court, and rose to positions of trust.", "bm_061"),
 ("vo", "Frumentius later traveled to Alexandria, where Bishop Athanasius made him the first bishop of Aksum. Ethiopians still call him Abba Salama, father of peace.", "bm_162"),
 ("vo", "Around the same time, King Ezana's coins change. The old symbols of the disc and crescent give way to the cross.", "bent_211"),
 ("vo", "So Ethiopia became one of the first kingdoms anywhere to take Christianity as its faith, in the fourth century.", "bm_178"),

 # ---------------------------------------------------------------- III
 ("chapter", "III|The Man in the Chariot", "bq_231"),
 ("vo", "Ethiopian Christians often point to an older story. In the Book of Acts, the apostle Philip meets an African official on the desert road to Gaza.", "bq_231"),
 ("quote", "And, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship.|Acts 8:27 (King James Version)", "bq_231"),
 ("vo", "He is reading the prophet Isaiah in his chariot. Philip explains it, and baptizes him beside the road.", "bq_201"),
 ("vo", "In fairness, the Ethiopia of the Bible usually means the kingdom of Kush, on the Nile in today's Sudan, and Candace was the title of its queens. But for Ethiopians, this man is the first of their faith.", "bq_201"),

 # ---------------------------------------------------------------- IV
 ("chapter", "IV|Into Ge'ez", "ms_geez_2"),
 ("vo", "Over the next few centuries, the Scriptures were translated from Greek into Ge'ez, the language of Aksum. Tradition credits a group of monks remembered as the Nine Saints.", "ms_geez_2"),
 ("vo", "Here is the important part. The translators worked from the Greek Old Testament, which was already bigger than the Hebrew Bible, and from other Jewish books still in circulation, including some that were disappearing elsewhere.", "bq_102"),
 ("vo", "Then Aksum declined, the Red Sea trade passed to new powers, and over the following centuries the church in the highlands grew more and more isolated.", "bent_184"),
 ("vo", "Elsewhere, councils and scholars narrowed their lists. In Ethiopia, nobody took the old books away. They were simply copied, by hand, generation after generation.", "bm_190"),

 # ---------------------------------------------------------------- V
 ("chapter", "V|The Book of Enoch", "dore_004"),
 ("vo", "The most famous of them is the Book of Enoch. It tells of angels called the Watchers, who came down to earth, took human wives, and fathered giants, before the Flood.", "dore_004"),
 ("vo", "The New Testament letter of Jude quotes it directly.", "bq_369"),
 ("quote", "And Enoch also, the seventh from Adam, prophesied of these, saying, Behold, the Lord cometh with ten thousands of his saints.|Jude 14 (King James Version)", "bq_369"),
 ("vo", "Early Christian writers read it. Then, in most of the world, it faded away. Fragments in Aramaic turned up among the Dead Sea Scrolls, but no complete copy survives in any language except Ge'ez.", "ms_geez_1"),
 ("vo", "Europe only got it back in the 1770s, when the Scottish explorer James Bruce brought three copies home from Ethiopia. Richard Laurence published the first English translation in 1821.", "ms_geez_3"),
 ("vo", "The same is true of the Book of Jubilees, a retelling of Genesis said to be revealed to Moses on Sinai. Complete, it exists only because Ethiopia kept it.", "bq_111"),

 # ---------------------------------------------------------------- VI
 ("chapter", "VI|Books Few Have Heard Of", "dore_046"),
 ("vo", "Alongside Enoch and Jubilees, the Ethiopian Old Testament holds books with familiar names and unfamiliar stories.", "dore_046"),
 ("vo", "There are three books of Meqabyan. The word means Maccabees, but they are not the Maccabees of the Catholic Bible. Their content is completely different.", "bm_182"),
 ("vo", "There is the Paralipomena of Jeremiah, also called Fourth Baruch. In it, Jerusalem is about to fall. A servant of the prophet Jeremiah, Abimelech, is sent out to gather figs, sits down in the shade, and falls asleep.", "dore_046"),
 ("vo", "He wakes up sixty six years later. The figs in his basket are still fresh.", "dore_046"),
 ("vo", "The Ethiopian canon also includes the books Catholics call deuterocanonical, like Tobit, Judith and Wisdom, along with the Prayer of Manasseh and further books of Ezra.", "bq_131"),

 # ---------------------------------------------------------------- VII
 ("chapter", "VII|The Twist in the Number", "bq_102"),
 ("vo", "So, which eighty one books exactly? This is where it gets interesting. The number is fixed. The list is not.", "bq_102"),
 ("vo", "The medieval law book of the Ethiopian church, the Fetha Negest, says the Scriptures have eighty one books, but the list it actually gives is shorter.", "bm_190"),
 ("vo", "Scholars describe two ways of counting. A narrower canon, which counts the Old Testament books in detail and keeps the New Testament at the usual twenty seven.", "bq_141"),
 ("vo", "And a broader canon, which adds books of church order to the New Testament: the Sinodos, two books of the Covenant, an Ethiopic Clement, and the Didascalia.", "bq_151"),
 ("vo", "Different counts, same number. For the church, eighty one is the shape of the whole, not a table of contents.", "bq_161"),

 # ---------------------------------------------------------------- VIII
 ("chapter", "VIII|The Garima Gospels", "bm_166"),
 ("vo", "Now to the monastery. At Abba Garima, near the town of Adwa in Tigray, monks have kept two illustrated Gospel books for centuries.", "bm_166"),
 ("vo", "Legend says the saint Garima copied them in a single day, and God held back the sun so he could finish. Scholars long assumed they were made much later, around the eleventh or twelfth century.", "bm_178"),
 ("vo", "Then, in the 2000s, an Oxford laboratory radiocarbon dated small samples of the parchment. The results pointed to between about the years three hundred and thirty and six hundred and fifty.", "bm_162"),
 ("vo", "That makes them among the oldest illustrated Christian books in the world. Their pages show the evangelists, canon tables, a picture of the Temple in Jerusalem, and more than twenty kinds of birds.", "bq_141"),
 ("vo", "Because the monks would not let the books leave, conservators from the Ethiopian Heritage Fund repaired them on site, in the monastery.", "bm_190"),

 # ---------------------------------------------------------------- IX
 ("chapter", "IX|The Glory of Kings", "dore_036"),
 ("vo", "There is one more Ethiopian book you should know, though it is not in the Bible at all. It is the Kebra Nagast, the Glory of Kings, put into Ge'ez in the fourteenth century.", "dore_036"),
 ("vo", "It tells how the Queen of Sheba traveled to King Solomon in search of wisdom.", "dore_036"),
 ("quote", "For I desire wisdom and my heart seeketh to find understanding. I am smitten with the love of wisdom.|Kebra Nagast 24 (tr. E. A. Wallis Budge, 1922)", "bq_014"),
 ("vo", "Their son, Menelik, grows up in Ethiopia, visits his father in Jerusalem, and when he returns home, the Ark of the Covenant goes with him.", "dore_030"),
 ("vo", "To this day, the church holds that the Ark rests in Aksum, in a chapel beside the Church of Our Lady Mary of Zion. Only one guardian monk may see it. No outsider can verify the claim, and most historians are skeptical.", "bent_184"),
 ("vo", "But every Ethiopian Orthodox church keeps a tabot, a consecrated tablet representing the Ark. Without it, a building is not a church.", "bm_178"),

 # ---------------------------------------------------------------- CLOSE
 ("chapter", "|A Library Kept Open", "bq_381"),
 ("vo", "So, why does the Ethiopian Bible have eighty one books? Not because someone added secret books. Because a church that received the Scriptures early kept almost everything it was given, and kept copying it, for sixteen centuries.", "bq_381"),
 ("vo", "Some of what survived, like Enoch and Jubilees, we would have lost without it. The open question is what else is still waiting, unread, in Ethiopia's monastery libraries.", "bq_014"),
 ("vo", "The King James Bible already had a line for it. Ethiopia shall soon stretch out her hands unto God.", "bm_166"),
 ("vo", "There are other lost books. The Book of the Wars of the Lord, which the Bible cites by name. The Protevangelium of James, the story of Mary's own childhood. And Second Enoch, the secrets of Enoch preserved in Slavonic.", "bq_161"),
 ("vo", "If you want to hear their stories, subscribe, and tell us in the comments which one we should open next.", "bq_161"),
 ("end", "THE LOST SCRIPTURES", "bq_161"),
]
